<?php
chdir(__DIR__.'/..');$d=json_decode(file_get_contents('data/catalogue.json'),true);$sheet=imagecreatetruecolor(1200,ceil(count($d['products'])/6)*145);$bg=imagecolorallocate($sheet,225,228,230);imagefill($sheet,0,0,$bg);$ink=imagecolorallocate($sheet,20,25,28);foreach($d['products'] as $i=>$p){$im=imagecreatefrompng($p['image']);$s=min(180/imagesx($im),110/imagesy($im));$w=(int)(imagesx($im)*$s);$h=(int)(imagesy($im)*$s);$x=($i%6)*200+(200-$w)/2;$y=floor($i/6)*145+(115-$h)/2;imagecopyresampled($sheet,$im,(int)$x,(int)$y,0,0,$w,$h,imagesx($im),imagesy($im));imagestring($sheet,2,($i%6)*200+8,(int)(floor($i/6)*145+122),($i+1).' '.substr($p['model'],0,24),$ink);imagedestroy($im);}imagepng($sheet,'images/extraction-review.png');
